                        // pending/red on the current head — branch protection
                        // unmet) and must survive; any other REST verdict on a
                        // fresh base ('behind', 'unknown') is a recompute lie —
                        // deterministically CLEAN.
                        ms = ms === 'BLOCKED' ? 'BLOCKED' : 'CLEAN';
